import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Discord Webhooks","description":"Set up Discord notifications for backup trigger, success, failure, and error events.","frontmatter":{"title":"Discord Webhooks","description":"Set up Discord notifications for backup trigger, success, failure, and error events."},"headers":[],"relativePath":"s3-database-storage-for-vps/user-guide/webhooks.md","filePath":"s3-database-storage-for-vps/user-guide/webhooks.md","lastUpdated":1782847089000}'),i={name:"s3-database-storage-for-vps/user-guide/webhooks.md"};function n(r,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="discord-webhooks" tabindex="-1">Discord Webhooks <a class="header-anchor" href="#discord-webhooks" aria-label="Permalink to &quot;Discord Webhooks&quot;">​</a></h1><p>The tool can post a rich embed to a <strong>Discord-compatible webhook</strong> whenever something happens. It&#39;s optional and configured in the setup wizard (Step 8).</p><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><p>During <code>sudo s3dbbackup setup</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Send alerts to a Discord webhook? [y/N] y</span></span>
<span class="line"><span>Discord webhook URL: https://discord.com/api/webhooks/123.../abc...</span></span>
<span class="line"><span>  Notify on &#39;trigger&#39;? [y/N] y</span></span>
<span class="line"><span>  Notify on &#39;success&#39;? [y/N] n</span></span>
<span class="line"><span>  Notify on &#39;failure&#39;? [Y/n] y</span></span>
<span class="line"><span>  Notify on &#39;error&#39;?   [Y/n] y</span></span></code></pre></div><p>To get a webhook URL: in Discord, open <strong>Server Settings → Integrations → Webhooks → New Webhook</strong>, pick a channel, and <strong>Copy Webhook URL</strong>.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>When it fires</th><th>Suggested</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>A backup cycle starts (lists the databases).</td><td>Optional</td></tr><tr><td><code>success</code></td><td>A database was backed up and uploaded. One per database.</td><td>Off on busy servers</td></tr><tr><td><code>failure</code></td><td>A specific database&#39;s dump or upload failed.</td><td><strong>On</strong></td></tr><tr><td><code>error</code></td><td>An unexpected error (e.g. S3 client couldn&#39;t initialise).</td><td><strong>On</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Recommended</p><p>Enable <strong><code>failure</code></strong> and <strong><code>error</code></strong> so you only hear from it when something is wrong. Add <code>success</code>/<code>trigger</code> if you want a heartbeat that backups are running.</p></div><h2 id="what-the-messages-look-like" tabindex="-1">What the messages look like <a class="header-anchor" href="#what-the-messages-look-like" aria-label="Permalink to &quot;What the messages look like&quot;">​</a></h2><p>Each notification is a colored embed titled <code>S3 DB Backup — &lt;event&gt;</code>:</p><ul><li><strong>Trigger</strong> (blue) — &quot;Starting backup for <em>N</em> database(s)&quot; with the list.</li><li><strong>Success</strong> (green) — database name, type, size, and the S3 key.</li><li><strong>Failure</strong> (red) — the database name and the error reason.</li><li><strong>Error</strong> (orange) — the operation and a trimmed traceback.</li></ul><h2 id="reliability" tabindex="-1">Reliability <a class="header-anchor" href="#reliability" aria-label="Permalink to &quot;Reliability&quot;">​</a></h2><p>Notifications never block or break a backup. If Discord is unreachable or the webhook is invalid, the failure is ignored silently and the backup continues.</p><h2 id="changing-it-later" tabindex="-1">Changing it later <a class="header-anchor" href="#changing-it-later" aria-label="Permalink to &quot;Changing it later&quot;">​</a></h2><p>Re-run the wizard and adjust Step 8:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>Or edit the <code>notifications</code> block in <a href="/pingless-studios-docs/s3-database-storage-for-vps/configuration/reference#notifications-discord-alerts"><code>/etc/s3dbbackup/config.json</code></a> directly.</p>`,18)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
